"""Self-contained dashboard; no external scripts, fonts, or network resources."""
HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>axispyPTZ · Camera desk</title>
<style>
:root{color-scheme:dark;--bg:#0b1019;--card:#141d2b;--line:#29364a;--text:#edf3fa;--muted:#96a8bf;--accent:#5de3c4}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px system-ui,sans-serif}main{max-width:1920px;margin:auto;padding:40px 28px}header{display:flex;align-items:center;justify-content:space-between;gap:18px}h1{font-size:25px;letter-spacing:-1px;margin:0}h1 span{color:var(--accent)}.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:2px;color:var(--muted);margin:8px 0 0}button{background:#1c293b;color:var(--text);border:1px solid #3c506b;border-radius:9px;padding:10px 18px;cursor:pointer;font:inherit}button:hover{border-color:var(--accent)}button[aria-expanded=true]{color:var(--accent);border-color:var(--accent)}.summary{margin:32px 0 24px;padding:22px;border:1px solid var(--line);border-radius:12px;display:flex;justify-content:space-between;align-items:center;gap:16px}.summary strong{font-size:24px;display:block;margin-top:5px}.muted{color:var(--muted)}.status{font-size:13px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:7px;background:#8799b0}.online .dot{background:var(--accent)}.offline .dot{background:#ff868b}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px}.camera{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px;min-width:0}.camera.selected{border-color:var(--accent);box-shadow:0 0 0 1px #5de3c41c}.top{display:flex;justify-content:space-between;gap:8px;align-items:center}.key{background:#233246;border:1px solid #3d5069;padding:4px 8px;border-radius:6px;font:bold 12px monospace}.tag{color:var(--accent);font-size:11px;text-transform:uppercase;letter-spacing:1px}.activity{display:flex;align-items:center;gap:9px;margin-top:18px;padding:10px 12px;border:1px solid var(--line);border-radius:8px;font-size:13px;color:var(--muted)}.activity .dot{margin:0;flex-shrink:0}.activity.active{color:var(--accent);border-color:#5de3c466;background:#5de3c40a}.activity.active .dot{background:var(--accent);box-shadow:0 0 8px #5de3c466}.activity.unknown .dot{background:#ffc77d}.camera h2{font-size:19px;margin:22px 0 9px;overflow-wrap:anywhere}.address{font:12px monospace;color:var(--muted);overflow-wrap:anywhere;min-height:34px;margin:14px 0}.detail{border-top:1px solid var(--line);padding-top:16px;margin-top:16px}.mode{font-size:19px;margin:6px 0}.note{font-size:12px;line-height:1.6;color:var(--muted);min-height:38px}.health-note{font-size:12px;line-height:1.6;color:var(--muted);margin-top:8px}.health-note:empty{display:none}.error{color:#ffb4b8;font-size:12px;overflow-wrap:anywhere;min-height:18px;margin-top:12px}.footer{display:flex;justify-content:space-between;gap:20px;font-size:12px;color:var(--muted);margin-top:22px}.debug{margin-top:28px;border:1px solid var(--line);border-radius:12px;overflow:hidden}.debug header{padding:16px 20px;background:var(--card)}.debug h2{font-size:15px;margin:0}pre{margin:0;padding:18px;background:#070c13;color:#c7e2d9;height:320px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.7 ui-monospace,monospace}.alert{color:#ffb4b8;min-height:20px;margin-top:12px}[hidden]{display:none!important}@media(max-width:1280px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){main{padding:24px 16px}.grid{grid-template-columns:1fr}.summary{align-items:flex-start;flex-direction:column}.footer{flex-direction:column;gap:6px}}
</style></head><body><main><header><div><h1>axis<span>py</span>PTZ <small class="muted" style="font-size:13px;letter-spacing:0">v0.2.5</small></h1><p class="eyebrow">Camera control desk</p></div><button id="debugButton" aria-expanded="false" aria-controls="debug">Debug logs</button></header>
<div class="summary"><div><span class="muted">Currently selected</span><strong id="selected">Waiting for controller…</strong></div><div><div id="joystick">Checking USB joystick…</div><div class="muted status" id="armed" style="margin-top:8px"></div></div></div>
<div id="cameras" class="grid"></div><div id="alert" role="status" class="alert"></div><div class="footer"><span>Read-only monitor · Use the joystick to control cameras</span><span id="updated">Connecting…</span></div>
<section class="debug" id="debug" hidden><header><h2>Live console log</h2><span class="muted status">Latest 1,000 messages</span></header><pre id="logs" aria-label="Live application logs"></pre></section>
</main><script>
const $=id=>document.getElementById(id);let debug=false,cursor=0,lines=[],pollIntervalMs=1000;
function node(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
function card(c){const box=node('article','camera'+(c.selected?' selected':''));const top=node('div','top');top.append(node('span','key','J'+c.slot),node('span','tag',c.selected?'Controlling':''));box.append(top,node('h2','',c.name));const availability=c.online===true?'online':c.online===false?'offline':'unknown';const state=node('div','status '+availability);state.append(node('span','dot'),document.createTextNode(c.online===true?'Online':c.online===false?'Offline':'Checking…'));box.append(state,node('div','address',c.url+' · channel '+c.channel));const activity=node('div','activity '+(c.ptz_activity||'unknown'));activity.setAttribute('role','status');activity.setAttribute('aria-label','PTZ command activity');activity.title='Controller command status; not measured camera movement';activity.append(node('span','dot'),document.createTextNode(c.ptz_activity==='active'?'PTZ · Active':c.ptz_activity==='idle'?'PTZ · Idle':'PTZ · Unconfirmed'));box.append(activity);const detail=node('div','detail');detail.append(node('span','muted status','Focus mode'),node('div','mode',c.focus==='auto'?'Autofocus':c.focus==='manual'?'Manual focus':'Unknown'));let note=c.focus_source==='camera'?'Reported by camera':c.focus_source==='command'?'Last successful controller command':'Waiting for focus status';if((c.online===false||c.error)&&c.focus!=='unknown')note+=' · last known';detail.append(node('div','note',note),node('div','error',[c.error,c.control_error].filter(Boolean).join(' · ')));box.append(detail,node('div','health-note',c.status_note||''),node('div','note',c.last_seen?'Last response '+new Date(c.last_seen).toLocaleTimeString():c.checked_at?'Checked '+new Date(c.checked_at).toLocaleTimeString():'Awaiting first check'));return box}
async function status(){try{const r=await fetch('/api/status',{cache:'no-store'});if(!r.ok)throw Error();const s=await r.json();if(Number.isInteger(s.poll_interval_ms)&&s.poll_interval_ms>=100&&s.poll_interval_ms<=60000)pollIntervalMs=s.poll_interval_ms;$('selected').textContent=s.cameras[s.selected]?.name||'No selection';$('joystick').textContent=s.joystick?'USB · '+s.joystick:'USB joystick disconnected — waiting';$('armed').textContent=s.armed?'Controls ready':'Movement inhibited · center stick and release focus buttons';$('cameras').replaceChildren(...s.cameras.map(card));$('updated').textContent='Updated '+new Date(s.time).toLocaleTimeString();$('alert').textContent=''}catch{$('alert').textContent='Dashboard connection lost. Retrying…'}}
async function logs(){if(!debug)return;try{const r=await fetch('/api/logs?after='+cursor,{cache:'no-store'});if(!r.ok)throw Error();const data=await r.json();if(data.cursor<cursor)lines=[];cursor=data.cursor;lines.push(...data.entries.map(e=>e.time+' '+e.level+' · '+e.message));lines=lines.slice(-1000);const p=$('logs');const follow=p.scrollTop+p.clientHeight>=p.scrollHeight-30;p.textContent=lines.join('\n');if(follow)p.scrollTop=p.scrollHeight}catch{}}
$('debugButton').addEventListener('click',()=>{debug=!debug;$('debug').hidden=!debug;$('debugButton').setAttribute('aria-expanded',String(debug));if(debug)logs()});
async function tick(){await status();await logs();setTimeout(tick,pollIntervalMs)}tick();
</script></body></html>'''
